**What this code covers**

- Two-way dictionary — lookup by key OR by value
- Number → word mapping
- {'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5}
- HTTP status code → description
- Bidirectional mapping class using dict comprehension
- Real use: stock ticker ↔ company name
- Transform config format (e.g., environment variables to Python naming)
- Environment variable style (UPPER_SNAKE) → Python style (lower_snake)

**Defines:** `BiMap`, `rot13_encode()`, `rot13_decode()`, `db_row_to_model()`, `model_to_db_row()`

### Example 1: Basic Key-Value Swap

```python
# Simple reversal patterns

# Number → word mapping
num_to_word = {1: 'one', 2: 'two', 3: 'three', 4: 'four', 5: 'five'}
word_to_num = {v: k for k, v in num_to_word.items()}
print(word_to_num)
# {'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5}

# Country → capital
country_to_capital = {
    'France':  'Paris',
    'Germany': 'Berlin',
    'Japan':   'Tokyo',
    'Brazil':  'Brasília',
    'India':   'New Delhi',
}
capital_to_country = {v: k for k, v in country_to_capital.items()}
print(capital_to_country['Tokyo'])   # Japan
print(capital_to_country['Paris'])   # France

# HTTP status code → description
status_codes = {200: 'OK', 201: 'Created', 400: 'Bad Request',
                404: 'Not Found', 500: 'Internal Server Error'}
description_to_code = {v: k for k, v in status_codes.items()}
print(description_to_code['Not Found'])   # 404
print(description_to_code['OK'])          # 200
```

### Example 2: Building Bidirectional Lookups

```python
# Bidirectional mapping class using dict comprehension

class BiMap:
    """Two-way dictionary — lookup by key OR by value"""

    def __init__(self, data: dict):
        self._forward = dict(data)
        self._reverse = {v: k for k, v in data.items()}

    def get(self, key):
        return self._forward.get(key)

    def get_key(self, value):
        return self._reverse.get(value)

    def __repr__(self):
        return f"BiMap({self._forward})"

# Real use: stock ticker ↔ company name
ticker_map = BiMap({
    'AAPL': 'Apple Inc.',
    'MSFT': 'Microsoft Corporation',
    'GOOGL': 'Alphabet Inc.',
    'AMZN': 'Amazon.com Inc.',
    'META': 'Meta Platforms Inc.',
})

print(ticker_map.get('AAPL'))              # 'Apple Inc.'
print(ticker_map.get_key('Apple Inc.'))    # 'AAPL'
print(ticker_map.get('MSFT'))              # 'Microsoft Corporation'
print(ticker_map.get_key('Amazon.com Inc.'))  # 'AMZN'
```

### Example 3: Config Key Transformation

```python
# Transform config format (e.g., environment variables to Python naming)

# Environment variable style (UPPER_SNAKE) → Python style (lower_snake)
env_vars = {
    'DATABASE_HOST': 'localhost',
    'DATABASE_PORT': '5432',
    'SECRET_KEY':    'abc123',
    'DEBUG_MODE':    'true',
    'MAX_WORKERS':   '4',
}

# Convert keys: 'DATABASE_HOST' → 'database_host'
python_config = {k.lower(): v for k, v in env_vars.items()}
print(python_config)
# {'database_host': 'localhost', 'database_port': '5432', ...}

# Reverse: Python config → env var format
env_format = {k.upper(): v for k, v in python_config.items()}
print(env_format)
# {'DATABASE_HOST': 'localhost', 'DATABASE_PORT': '5432', ...}

# Camel case keys → snake case values as lookup
# (e.g., from JavaScript API to Python backend)
camel_to_snake = {
    'firstName': 'first_name',
    'lastName':  'last_name',
    'emailAddress': 'email_address',
    'phoneNumber': 'phone_number',
    'dateOfBirth': 'date_of_birth',
}

# Build reverse: snake → camel (for serialization back to JSON)
snake_to_camel = {v: k for k, v in camel_to_snake.items()}
print(snake_to_camel['first_name'])   # 'firstName'
print(snake_to_camel['email_address'])  # 'emailAddress'
```

### Example 4: Cipher/Encoding Use Case

```python
# Encryption/encoding requires both encode and decode mappings

import string

# ROT13 cipher (rotate 13 positions)
alphabet = string.ascii_lowercase
encode_map = {c: alphabet[(i + 13) % 26] for i, c in enumerate(alphabet)}
decode_map = {v: k for k, v in encode_map.items()}  # ← Swap to decode!

print("Encode map (first 5):", dict(list(encode_map.items())[:5]))
# {'a': 'n', 'b': 'o', 'c': 'p', 'd': 'q', 'e': 'r'}

def rot13_encode(text):
    return ''.join(encode_map.get(c.lower(), c) for c in text)

def rot13_decode(text):
    return ''.join(decode_map.get(c.lower(), c) for c in text)

message = "hello world"
encoded = rot13_encode(message)
decoded = rot13_decode(encoded)

print(f"Original: {message}")    # hello world
print(f"Encoded:  {encoded}")    # uryyb jbeyq
print(f"Decoded:  {decoded}")    # hello world  ← back to original!

# ROT13 is self-inverse: encoding twice = original
print(rot13_encode(encoded) == message)  # True
```

### Example 5: Database Schema Mapping

```python
# ORM-style field mapping — common in data layers

# Database column names → Python attribute names
db_to_python = {
    'user_id':      'id',
    'first_name':   'first_name',
    'last_name':    'last_name',
    'email_addr':   'email',
    'created_at':   'created_at',
    'is_active':    'active',
    'phone_num':    'phone',
}

# Reverse: Python attribute → DB column (for UPDATE queries)
python_to_db = {v: k for k, v in db_to_python.items()}

# Transform DB row to Python dict
def db_row_to_model(row: dict) -> dict:
    return {
        db_to_python.get(col, col): value
        for col, value in row.items()
        if col in db_to_python  # Skip unmapped columns
    }

# Transform Python dict to DB row (for INSERT/UPDATE)
def model_to_db_row(model: dict) -> dict:
    return {
        python_to_db.get(field, field): value
        for field, value in model.items()
        if field in python_to_db  # Skip unmapped fields
    }

# Test
db_row = {'user_id': 101, 'first_name': 'Alice', 'email_addr': 'alice@co.com',
          'is_active': True, 'created_at': '2024-01-15', 'phone_num': '555-1234'}

python_model = db_row_to_model(db_row)
print("Python model:", python_model)
# {'id': 101, 'first_name': 'Alice', 'email': 'alice@co.com',
#  'active': True, 'created_at': '2024-01-15', 'phone': '555-1234'}

db_ready = model_to_db_row(python_model)
print("DB row:", db_ready)
# {'user_id': 101, 'first_name': 'Alice', 'email_addr': 'alice@co.com', ...}
```
